from collections import deque
links = {"a": ["b", "c"], "b": ["a", "d"], "c": ["d"], "d": ["e"], "e": []}
def crawl(start, max_depth):
    seen, order = {start}, []
    q = deque([(start, 0)])
    while q:
        url, d = q.popleft()
        order.append(url)
        if d == max_depth:
            continue
        for nxt in links[url]:
            if nxt not in seen:
                seen.add(nxt)
                q.append((nxt, d + 1))
    return order
print(crawl("a", 2))

